  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2019, 2021],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.11/yr, peak A/E 1.34",
      "confidence": 0.75,
      "evidence": [
        "ae_death_by_year.csv: A/E rises sustainingly from 1.11 (2019) to 1.16 (2020) to 1.34 (2021) above the ~0.95 baseline, then reverts to 0.80/0.95/0.97 in 2022-2024."
      ],
      "recommended_action": "Investigate mortality claims frequency/severity and policy mix in 2019-2021 (e.g., pandemic or coding changes); review mortality assumptions in pricing and valuation; monitor 2023-2024 to distinguish structural shift from transient effect."
    },
    {
      "benefit": "IP",
      "years": [2019, 2022],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.05/yr, peak A/E 1.20",
      "confidence": 0.85,
      "evidence": [
        "ae_ip_by_year.csv: A/E climbs steadily from 1.04 (2019) to 1.08 (2020) to 1.11 (2021) to 1.20 (2022), followed by a drop to 0.91/0.94 in 2023-2024."
      ],
      "recommended_action": "Review IP claims duration, frequency, and benefit utilisation in 2019-2022; assess external drivers (e.g., economic/health trends, claims handling); update reserving and pricing models if elevated experience persists or reflects a new norm."
    }
  ]
}

